'pomerol-chateau-rouget|2007':{blend:{ME:85,CF:15},months:'18',oak:33,src:'chateau-rouget-2007-21.pdf',window:'This wine will be enjoyable from today, and will go on developing for another ten to fifteen years.',wtl:1},
