'la-tour-blanche|2021':{alc:13.5,yld:20,src:'FT-CHATEAU-LA-TOUR-BLANCHE-2021-A4-1.pdf',months:'16-18',note:'Château La Tour Blanche 2021 Château La Tour Blanche 1st Grand Cru Classé of Sauternes in 1855 Harvest period & Blend Manual Harvest 3 pickings Only new oak Only new oak barrel',sug:137,wy:[2027,2042]},
